/*========================
  Gallery style start
==========================*/
.gallery-section {
  padding: calc(50px + 30 * (100vw - 320px) / 1600) 0;
}
.gallery-section .gallery-header {
  margin-bottom: calc(30px + 20 * (100vw - 320px) / 1600);
}
.gallery-section .gallery-header .gallery-title {
  font-size: calc(28px + 14 * (100vw - 320px) / 1600);
  font-weight: 600;
  color: rgba(var(--title-color), 1);
  margin-bottom: 15px;
}
.gallery-section .gallery-header .gallery-subtitle {
  font-size: calc(16px + 2 * (100vw - 320px) / 1600);
  color: rgba(var(--content-color), 1);
  margin-bottom: 0;
}
.gallery-section .gallery-header .btn-back {
  background: transparent;
  border: 1px solid rgba(var(--border-color), 1);
  color: rgba(var(--title-color), 1);
  padding: calc(8px + 4 * (100vw - 320px) / 1600) calc(15px + 5 * (100vw - 320px) / 1600);
  border-radius: 5px;
  font-size: calc(14px + 2 * (100vw - 320px) / 1600);
  cursor: pointer;
  transition: all 0.3s ease;
}
.gallery-section .gallery-header .btn-back:hover {
  background: rgba(var(--theme-color), 1);
  border-color: rgba(var(--theme-color), 1);
  color: rgba(var(--white), 1);
}
.gallery-section .gallery-event-card {
  cursor: pointer;
  border-radius: 12px;
  overflow: hidden;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
  height: 100%;
}
.gallery-section .gallery-event-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.15);
}
.gallery-section .gallery-event-card .event-thumbnail-wrapper {
  position: relative;
  width: 100%;
  height: calc(250px + 150 * (100vw - 320px) / 1600);
  overflow: hidden;
  border-radius: 12px;
}
.gallery-section .gallery-event-card .event-thumbnail-wrapper .event-thumbnail {
  transition: transform 0.5s ease;
}
.gallery-section .gallery-event-card .event-thumbnail-wrapper .event-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(to bottom, transparent 0%, rgba(0, 0, 0, 0.7) 100%);
  display: flex;
  align-items: flex-end;
  padding: calc(15px + 10 * (100vw - 320px) / 1600);
  opacity: 0;
  transition: opacity 0.3s ease;
}
.gallery-section .gallery-event-card .event-thumbnail-wrapper:hover .event-thumbnail {
  transform: scale(1.1);
}
.gallery-section .gallery-event-card .event-thumbnail-wrapper:hover .event-overlay {
  opacity: 1;
}
.gallery-section .gallery-event-card .event-thumbnail-wrapper .event-info {
  width: 100%;
  color: rgba(var(--white), 1);
}
.gallery-section .gallery-event-card .event-thumbnail-wrapper .event-info .event-title {
  font-size: calc(20px + 8 * (100vw - 320px) / 1600);
  font-weight: 600;
  margin-bottom: calc(8px + 4 * (100vw - 320px) / 1600);
  color: rgba(var(--white), 1);
}
.gallery-section .gallery-event-card .event-thumbnail-wrapper .event-info .event-description {
  font-size: calc(14px + 2 * (100vw - 320px) / 1600);
  margin-bottom: calc(8px + 4 * (100vw - 320px) / 1600);
  color: rgba(var(--white), 0.9);
}
.gallery-section .gallery-event-card .event-thumbnail-wrapper .event-info .event-date,
.gallery-section .gallery-event-card .event-thumbnail-wrapper .event-info .event-count {
  display: inline-block;
  font-size: calc(12px + 2 * (100vw - 320px) / 1600);
  padding: calc(4px + 2 * (100vw - 320px) / 1600) calc(8px + 4 * (100vw - 320px) / 1600);
  background: rgba(var(--theme-color), 0.8);
  border-radius: 4px;
  margin-right: 8px;
  margin-top: 5px;
}
.gallery-section .gallery-image-wrapper {
  position: relative;
  width: 100%;
  height: calc(200px + 100 * (100vw - 320px) / 1600);
  border-radius: 8px;
  overflow: hidden;
  cursor: pointer;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}
.gallery-section .gallery-image-wrapper:hover {
  transform: translateY(-5px);
  box-shadow: 0 8px 25px rgba(0, 0, 0, 0.15);
}
.gallery-section .gallery-image-wrapper:hover .image-overlay {
  opacity: 1;
}
.gallery-section .gallery-image-wrapper:hover .gallery-image {
  transform: scale(1.1);
}
.gallery-section .gallery-image-wrapper .gallery-image {
  transition: transform 0.5s ease;
}
.gallery-section .gallery-image-wrapper .image-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: opacity 0.3s ease;
}
.gallery-section .gallery-image-wrapper .image-overlay i {
  font-size: calc(30px + 10 * (100vw - 320px) / 1600);
  color: rgba(var(--white), 1);
}
@media (max-width: 991px) {
  .gallery-section .gallery-event-card .event-thumbnail-wrapper {
    height: calc(220px + 80 * (100vw - 576px) / 415);
  }
  .gallery-section .gallery-image-wrapper {
    height: calc(180px + 70 * (100vw - 576px) / 415);
  }
}
@media (max-width: 767px) {
  .gallery-section .gallery-event-card .event-thumbnail-wrapper {
    height: calc(200px + 80 * (100vw - 320px) / 447);
  }
  .gallery-section .gallery-event-card .event-thumbnail-wrapper .event-overlay {
    opacity: 1;
    background: linear-gradient(to bottom, transparent 0%, rgba(0, 0, 0, 0.6) 100%);
  }
  .gallery-section .gallery-image-wrapper {
    height: calc(160px + 60 * (100vw - 320px) / 447);
  }
}

